"use client";

import { motion } from "framer-motion";
import { User, DollarSign } from "lucide-react";

interface TopCustomersProps {
  customers: {
    name: string;
    totalSpend: number;
  }[];
}

export default function TopCustomers({ customers }: TopCustomersProps) {
  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-full"
    >
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-lg font-semibold text-slate-800 tracking-tight">
          Top Customers
        </h2>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-widest">
          By Lifetime Value
        </span>
      </div>

      <div className="space-y-4">
        {customers.map((customer, index) => (
          <div
            key={index}
            className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-600">
                <User size={18} />
              </div>
              <div>
                <p className="font-semibold text-slate-900">{customer.name}</p>
                <p className="text-xs text-slate-500">Premium Tier</p>
              </div>
            </div>
            <div className="text-right">
              <p className="font-bold text-slate-900 flex items-center justify-end gap-1">
                <DollarSign size={14} className="text-emerald-500" />
                {customer.totalSpend.toLocaleString()}
              </p>
              <div className="w-24 h-1.5 bg-slate-100 rounded-full mt-2 overflow-hidden">
                <div 
                  className="h-full bg-emerald-500 rounded-full" 
                  style={{ width: `${(customer.totalSpend / customers[0].totalSpend) * 100}%` }}
                />
              </div>
            </div>
          </div>
        ))}

        {customers.length === 0 && (
          <div className="text-center py-10">
            <p className="text-slate-400 text-sm">No customer data available yet.</p>
          </div>
        )}
      </div>
    </motion.div>
  );
}
